const AuthBar = ({
  userEmail,
  badgeLabel = 'Early access',
  signInLabel = 'Sign in',
  logoutLabel = 'Log out',
  onSignIn,
  onLogout
}) => {
  const isAuthed = Boolean(userEmail);

  return (
    <div className="flex items-center gap-3">
      {isAuthed ? (
        <>
          <div className="flex items-center gap-2 rounded-full border border-white/20 bg-white/10 px-4 py-2 text-xs font-semibold uppercase tracking-[0.3em] text-white/70">
            <span>{badgeLabel}</span>
            <span className="normal-case text-[11px] font-medium tracking-normal text-white/60">
              {userEmail}
            </span>
          </div>
          {onLogout && (
            <button
              type="button"
              onClick={onLogout}
              className="rounded-full border border-white/20 bg-white/10 px-4 py-2 text-[11px] font-semibold uppercase tracking-[0.3em] text-white/70 hover:bg-white/20"
            >
              {logoutLabel}
            </button>
          )}
        </>
      ) : (
        <button
          type="button"
          onClick={onSignIn}
          className="rounded-full border border-white/20 bg-white/10 px-4 py-2 text-xs font-semibold uppercase tracking-[0.3em] text-white/70 hover:bg-white/20"
        >
          {signInLabel}
        </button>
      )}
    </div>
  );
};

export default AuthBar;
